using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class B3RepairApply {
 const string A="Assets/Afrer_Seconds/05.Model/",E=A+"Environment/B3/";
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));static string H=>R+"/SourceAssets/B3_StructureRepair/";static Dictionary<string,Material> mats;static Transform root;static int clean;
 static Vector3 V(JToken t)=>new Vector3((float)t[0],(float)t[1],(float)t[2]);
 static Material Map(Material m){if(!m)throw new Exception("Missing material");if(m.name.StartsWith("B4O_")&&mats.TryGetValue("B3M_"+m.name.Substring(4),out var target))return target;return m;}
 static void Record(GameObject g){foreach(var c in g.GetComponentsInChildren<Component>(true))if(c&&PrefabUtility.IsPartOfPrefabInstance(c))PrefabUtility.RecordPrefabInstancePropertyModifications(c);}
 static Mesh Surface(Mesh src,Transform tf,Material[] ms,string name){var vv=src.vertices;var nn=src.normals;var uu=src.uv;var vs=new List<Vector3>();var ns=new List<Vector3>();var uv=new List<Vector2>();var subs=new List<int[]>();var cache=new Dictionary<long,int>();for(int s=0;s<src.subMeshCount;s++){bool wall=ms[s].name.Contains("Coat"),floor=ms[s].name.Contains("Floor");if(wall)ms[s]=mats["BS_WallWear"];if(floor)ms[s]=mats["BS_FloorWear"];var ix=src.GetTriangles(s);var dst=new List<int>();for(int i=0;i<ix.Length;i+=3){var n=Vector3.Cross(vv[ix[i+1]]-vv[ix[i]],vv[ix[i+2]]-vv[ix[i]]);if(n.sqrMagnitude<1e-16f){clean++;continue;}var wn=tf.TransformDirection(n);int axis=Mathf.Abs(wn.x)>Mathf.Abs(wn.z)?0:1;for(int k=0;k<3;k++){int vi=ix[i+k];long key=(long)vi*8+(floor?4:wall?axis+1:0);if(!cache.TryGetValue(key,out var at)){at=vs.Count;cache[key]=at;vs.Add(vv[vi]);ns.Add(nn.Length==vv.Length?nn[vi]:n.normalized);var wp=tf.TransformPoint(vv[vi]);uv.Add(floor?new Vector2(wp.x/4,wp.z/4):wall?new Vector2((axis==0?wp.z:wp.x)/6,Mathf.Max(.005f,wp.y+49)/4):uu.Length==vv.Length?uu[vi]:Vector2.zero);}dst.Add(at);}}subs.Add(dst.ToArray());}var mesh=new Mesh{name=name,indexFormat=vs.Count>65535?IndexFormat.UInt32:IndexFormat.UInt16};mesh.SetVertices(vs);mesh.SetNormals(ns);mesh.SetUVs(0,uv);mesh.subMeshCount=subs.Count;for(int i=0;i<subs.Count;i++)mesh.SetTriangles(subs[i],i,false);mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,E+name+".asset");return mesh;}
 static void Replace(Transform g,string model,bool surface){var src=AssetDatabase.LoadAssetAtPath<GameObject>(E+model+".fbx");var sm=src.GetComponentsInChildren<MeshFilter>().Single();var mf=g.GetComponentsInChildren<MeshFilter>(true).Single();var ms=sm.GetComponent<MeshRenderer>().sharedMaterials.Select(Map).ToArray();mf.sharedMesh=surface?Surface(sm.sharedMesh,mf.transform,ms,"BR_Surface_"+model):sm.sharedMesh;mf.GetComponent<MeshRenderer>().sharedMaterials=ms;foreach(var c in g.GetComponentsInChildren<MeshCollider>(true))c.sharedMesh=mf.sharedMesh;Record(g.gameObject);}
 static Vector3 At(List<Vector3> p,float d,out Vector3 tangent){for(int i=1;i<p.Count;i++){float length=Vector3.Distance(p[i-1],p[i]);if(d<=length){tangent=(p[i]-p[i-1]).normalized;return Vector3.Lerp(p[i-1],p[i],Mathf.Clamp01(d/length));}d-=length;}tangent=(p[p.Count-1]-p[p.Count-2]).normalized;return p[p.Count-1];}
 public static object Run(){var scene=SceneManager.GetActiveScene();if(Application.isPlaying||scene.isDirty||!scene.path.EndsWith("Level_B3_Circular.unity"))throw new Exception("Saved B3 required; coordinate with user before switching scenes");root=scene.GetRootGameObjects().Single(g=>g.name=="B3_Circular_SampleFloor").transform;if(root.GetComponentsInChildren<Transform>(true).Any(t=>t.name.StartsWith("BR_B3_T08_TunnelRib")))throw new Exception("Repair already applied");var plan=JObject.Parse(File.ReadAllText(H+"layout_after.json"));var delta=JObject.Parse(File.ReadAllText(H+"density_delta.json"));mats=AssetDatabase.FindAssets("t:Material",new[]{E+"Materials",A+"Props/B3/Materials"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<Material>).GroupBy(m=>m.name).ToDictionary(g=>g.Key,g=>g.First());var tunnel=plan["tunnels"].Single(t=>(string)t["id"]=="B3-T08");var path=tunnel["path"].Select(p=>new Vector3((float)p[0],0,-(float)p[1])).ToList();float length=(float)tunnel["length"];
 foreach(string id in new[]{"C03","C04"}){var sector=root.Find("B3_"+id+"_Sector");foreach(string part in new[]{"Shell","Lining","Services"})Replace(sector.Find("Architecture/B3_"+id+"_"+part),"BR_B3_"+id+"_"+part,part!="Services");var r=plan["rooms"].Single(x=>(string)x["id"]==id);var doors=r["doors"].ToArray();int di=Array.FindIndex(doors,d=>(string)d["id"]=="B3-T08");var dir=new Vector3((float)doors[di]["x"],0,(float)doors[di]["z"]).normalized;float radius=(float)r["r"];var portal=sector.Find("Architecture/B3_"+id+"_VaultPortal_B3-T08");portal.localPosition=dir*(radius-.38f);portal.localRotation=Quaternion.LookRotation(dir);Record(portal.gameObject);var light=sector.Find("EmergencyLighting/B3_"+id+"_DoorEmergency_"+(di+1));light.localPosition=dir*(radius-.65f)+Vector3.up*3.1f;light.localRotation=Quaternion.LookRotation(dir);Record(light.gameObject);
 foreach(Transform g in sector.Find("WorkLighting")){var p=g.localPosition;var flat=new Vector3(p.x,0,p.z);if(p.y<3.66f&&Vector3.Angle(flat,dir)<Mathf.Asin(Mathf.Min(.95f,2.7f/radius))*Mathf.Rad2Deg){var n=flat.normalized;g.localPosition=n*(Mathf.Sqrt(radius*radius-3.85f*3.85f)-.20f)+Vector3.up*3.85f;var normal=(g.localPosition-(n*(radius-2.5f)+Vector3.up)).normalized;g.localRotation=Quaternion.LookRotation(Vector3.Cross(Vector3.Cross(Vector3.up,n),normal),normal);Record(g.gameObject);}}
 }
 var corridor=root.Find("B3_Corridors").Cast<Transform>().Single(t=>t.name.StartsWith("B3_T08_"));var shell=corridor.Find("B3_T08_TunnelShell");Replace(shell,"BR_B3_T08_Shell",true);var finish=corridor.Find("B3_T08_TunnelFinish");finish.localPosition=Vector3.zero;finish.localRotation=Quaternion.identity;Replace(finish,"BR_B3_T08_Finish",false);
 var oldRibs=corridor.Cast<Transform>().Where(t=>t.name.Contains("_TunnelRib_")).ToArray();var oldLights=corridor.Cast<Transform>().Where(t=>t.name.Contains("_BetweenRibsLight_")).ToArray();int count=Mathf.CeilToInt((length-1.2f)/3f);float span=(length-1.2f)/count;for(int i=0;i<=count;i++){var pos=At(path,.6f+i*span,out var dir);var go=UnityEngine.Object.Instantiate(oldRibs[0].gameObject,corridor);go.name="BR_B3_T08_TunnelRib_"+i.ToString("000");go.transform.localPosition=pos;go.transform.localRotation=Quaternion.LookRotation(dir);Record(go);if(i<count&&(i%3==0||i==count-1)){pos=At(path,.6f+(i+.5f)*span,out dir);var lamp=UnityEngine.Object.Instantiate(oldLights[0].gameObject,corridor);lamp.name="BR_B3_T08_BetweenRibsLight_"+i.ToString("000");lamp.transform.localPosition=pos+Vector3.up*3.31f;lamp.transform.localRotation=Quaternion.LookRotation(dir);Record(lamp);}}foreach(var t in oldRibs.Concat(oldLights)){t.gameObject.SetActive(false);Record(t.gameObject);}
 var guidance=root.Find("B3_CorridorGuidance");var oldGuides=guidance.Cast<Transform>().Where(t=>t.name.StartsWith("B3_T08_")).ToArray();var usable=path.Where(v=>Vector3.Distance(v,new Vector3(-29,0,-20))>6.22f&&Vector3.Distance(v,new Vector3(24,0,-15))>8.22f).ToList();foreach(int side in new[]{-1,1}){string dest=side<0?"C03":"C04";var vs=new List<Vector3>();for(int i=0;i<usable.Count;i++){var dir=(usable[Mathf.Min(i+1,usable.Count-1)]-usable[Mathf.Max(0,i-1)]).normalized;var right=Vector3.Cross(Vector3.up,dir);foreach(float x in new[]{-.0275f,.0275f})vs.Add(usable[i]+right*(side*.12f+x)+Vector3.up*.009f);}var ix=new List<int>();for(int i=0;i<usable.Count-1;i++){int j=i*2;ix.AddRange(new[]{j,j+2,j+1,j+1,j+2,j+3});}var m=new Mesh{name="BR_B3_T08_LineTo_"+dest};m.SetVertices(vs);m.SetTriangles(ix,0);m.RecalculateNormals();m.RecalculateBounds();AssetDatabase.CreateAsset(m,E+m.name+".asset");var g=new GameObject(m.name);g.transform.SetParent(guidance,false);g.AddComponent<MeshFilter>().sharedMesh=m;g.AddComponent<MeshRenderer>().sharedMaterial=mats["BS_Line_"+dest];var old=oldGuides.Single(t=>t.name=="B3_T08_LabelTo_"+dest);var label=UnityEngine.Object.Instantiate(old.gameObject,guidance);label.name="BR_B3_T08_LabelTo_"+dest;label.transform.localPosition=At(path,side<0?3.0f:length-3.0f,out var direction)+Vector3.Cross(Vector3.up,direction)*(side*.85f)+Vector3.up*.015f;label.transform.localRotation=Quaternion.LookRotation(direction)*Quaternion.Euler(0,side<0?90:-90,0);}
 foreach(var t in oldGuides)t.gameObject.SetActive(false);
 foreach(var item in delta["moves"]){var q=item["new"];var g=root.Find("B3_"+(string)q["room"]+"_Sector/Equipment/"+(string)q["name"]);if(!g)throw new Exception("Missing moved prop "+q["name"]);g.localPosition=V(q["position"]);g.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);Record(g.gameObject);}
 int added=0;foreach(var q in delta["additions"]){var parent=root.Find("B3_"+(string)q["room"]+"_Sector/Equipment");var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>((string)q["asset"]),parent);g.name=(string)q["name"];g.transform.localPosition=V(q["position"]);g.transform.localRotation=Quaternion.Euler(0,(float)q["yaw"],0);foreach(var c in g.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var mr in g.GetComponentsInChildren<MeshRenderer>(true))mr.sharedMaterials=mr.sharedMaterials.Select(Map).ToArray();if((string)q["role"]!="BenchAccessory"){var bc=g.AddComponent<BoxCollider>();bc.center=V(q["center"]);bc.size=V(q["size"]);}Record(g);added++;}
 Physics.SyncTransforms();AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.Copy(H+"layout_after.json",R+"/SourceAssets/B3_FullFloor/layout.json",true);var result=new{tunnel="T08",length,replacedMeshes=8,oldRibsDisabled=oldRibs.Length,newRibs=count+1,addedProps=added,movedProps=delta["moves"].Count(),degenerateRemoved=clean,sceneSaved=!scene.isDirty};File.WriteAllText(R+"/Docs/Review/2026-11-09_B3_StructureRepair/apply.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;
 }
